from pathlib import Path

source = Path(sys.argv[1]).read_text()
checks = [
    (
        "private void finishBottomLikeControlOpen(",
        "private void selectTabForTyping(",
        "finishBottomLikeControlOpen",
    ),
    (
        "private void finishSelectedTabOpen(",
        "private void settleSelectedTabViewport(",
        "finishSelectedTabOpen",
    ),
]
for start_marker, end_marker, name in checks:
    try:
        start = source.index(start_marker)
        end = source.index(end_marker, start)
    except ValueError:
        print(f"Phone plan regression guard failed: could not locate {name}", file=sys.stderr)
        sys.exit(1)
    body = source[start:end]
    if "focusTerminalInputSoon(false);" in body:
        print(
            f"Phone plan regression guard failed: {name} must not refocus xterm after passive tab-open",
            file=sys.stderr,
        )
        sys.exit(1)
print("passive tab-open focus guard passed")
