    require "$CLAUDE_SPEC_PHASE0_PROOF" 'wildcard CORS on control responses' "Claude Phase 0 proof must keep wildcard CORS blocked after browser overlay work"
    require "$CLAUDE_SPEC_PHASE0_PROOF" 'phone-terminal url must point at the authenticated web shell, not raw ttyd' "Claude Phase 0 proof must guard the browser URL against raw-ttyd regressions"
    require "$CLAUDE_SPEC_PHASE0_PROOF" 'phone-terminal must keep the localhost browser bridge for Windows Chrome proof' "Claude Phase 0 proof must guard the desktop browser bridge"
    "$CLAUDE_SPEC_PHASE0_PROOF"
else
    echo "Phone plan regression guard failed: missing Claude-spec Phase 0 proof script" >&2
    echo "File: $CLAUDE_SPEC_PHASE0_PROOF" >&2
    exit 1
fi

if [ -f "$BROWSER_PARITY_PROOF" ]; then
    # WHY: browser parity is not proven by serving HTML or by a curl probe. The
    # user specifically hit a web link that showed raw terminal without the APK
    # controls. Keep a real rendered-browser proof script registered so future
    # web work must prove the toolbar, dialogs, token gate, disposable New/Close,
    # Copy/Paste, Upload, Start/Stop, and APK hot-path invariants together.
    require "$BROWSER_PARITY_PROOF" 'button[data-action="active"]' "browser proof must click the rendered Active toolbar button"
    require "$BROWSER_PARITY_PROOF" 'mantis-phone-control-server' "browser proof must use the live Mantis control server by default"
    require "$BROWSER_PARITY_PROOF" '.mantis/phone-terminal/web-control-token' "browser proof must use the live Mantis web token by default"
    require "$BROWSER_PARITY_PROOF" 'split-brain auth layer' "browser proof must document why legacy web tokens are forbidden"
    require "$BROWSER_PARITY_PROOF" 'for label in Active Old Workspace New Refresh Bottom Scroll "Copy/Paste" Upload Close Start Stop' "browser proof must verify all APK-equivalent toolbar labels"
    require "$BROWSER_PARITY_PROOF" 'User-Agent: Mozilla/5.0' "browser proof must test browser-like requests, not only curl/API calls"
    require "$BROWSER_PARITY_PROOF" 'X-WEzTerm-CSRF' "browser proof must prove the CSRF header is required for browser mutations"
    require "$BROWSER_PARITY_PROOF" 'wildcard CORS is still live' "browser proof must fail if wildcard CORS returns"
    require "$BROWSER_PARITY_PROOF" 'wait_for_browser_created_window' "browser proof must isolate mutations to a newly-created disposable tmux window"
    require "$BROWSER_PARITY_PROOF" 'web Active switch shield' "browser proof must test the website Active-switch shield"
    require "$BROWSER_PARITY_PROOF" '__weztermWebSwitchShieldState' "browser proof must verify the web shield state in the rendered page"
    require "$BROWSER_PARITY_PROOF" 'dataset.windowId' "browser proof must select Active rows by explicit tmux window id"
    require "$BROWSER_PARITY_PROOF" 'web Active-switch shield did not activate' "browser proof must fail if the web shield does not activate"
    require "$BROWSER_PARITY_PROOF" 'did not hide web Active-switch shield' "browser proof must fail if the web shield does not hide after switching"
    require "$BROWSER_PARITY_PROOF" 'cleanup refused to close' "browser proof cleanup must refuse to close windows it did not title as disposable"
    require "$BROWSER_PARITY_PROOF" 'WEB_BROWSER_PASTE_' "browser proof must prove full text Copy/Paste through the web UI"
    require "$BROWSER_PARITY_PROOF" 'wezterm-web-upload-proof.txt' "browser proof must prove direct browser Upload"
    require "$BROWSER_PARITY_PROOF" 'Browser parity proof passed' "browser proof must have an explicit success receipt"
    require "$BROWSER_PARITY_PROOF" 'BROWSER_CONTROL_URL' "browser proof must distinguish the Windows-browser URL from the APK/Tailnet control URL"
    require "$BROWSER_PARITY_PROOF" 'ensure_browser_bridge' "browser proof must prove the localhost browser bridge is live"
else
    echo "Phone plan regression guard failed: missing browser parity proof script" >&2
    echo "File: $BROWSER_PARITY_PROOF" >&2
    exit 1
fi

if [ -f "$SCROLLBACK_CHUNK_PROOF" ]; then
    # WHY: local-first history cannot start by changing Android gestures. Prove
    # the server edge is bounded, read-only, token-gated for browsers, and leaves
    # the active tmux window/pane mode unchanged before any client cache work.
    require "$SCROLLBACK_CHUNK_PROOF" 'scrollback/chunk' "scrollback proof must exercise the C4 endpoint"
    require "$SCROLLBACK_CHUNK_PROOF" 'SCROLLBACK_CHUNK_PROOF_180' "scrollback proof must create bounded disposable history"
    require "$SCROLLBACK_CHUNK_PROOF" 'browser token read-only chunk without csrf' "scrollback proof must show browser token read does not require CSRF"
    require "$SCROLLBACK_CHUNK_PROOF" 'endpoint changed active window' "scrollback proof must fail if the endpoint selects windows"
    require "$SCROLLBACK_CHUNK_PROOF" 'endpoint changed pane mode' "scrollback proof must fail if the endpoint enters copy-mode"
    require "$SCROLLBACK_CHUNK_PROOF" 'Phone scrollback chunk proof passed' "scrollback proof must have an explicit success receipt"
else
    echo "Phone plan regression guard failed: missing scrollback chunk proof script" >&2
    echo "File: $SCROLLBACK_CHUNK_PROOF" >&2
    exit 1
fi

if [ -f "$LATENCY_BASELINE_PROOF" ]; then
    # WHY: performance work needs a baseline before changing behavior. This proof
    # keeps the C1 record cheap and repeatable so future local-history or typing
    # changes can compare real endpoint timings instead of guessing.
    require "$LATENCY_BASELINE_PROOF" 'PHONE_LATENCY_OUTPUT' "latency proof must write a reusable baseline artifact"
    require "$LATENCY_BASELINE_PROOF" 'mantis-phone-control-server' "latency proof must default to the live Mantis control server when installed"
    require "$LATENCY_BASELINE_PROOF" '.mantis/phone-terminal/web-control-token' "latency proof must prefer the live Mantis web token before the legacy token path"
    require "$LATENCY_BASELINE_PROOF" 'tabs_light' "latency proof must include the Active picker's fast light tabs endpoint"
    require "$LATENCY_BASELINE_PROOF" 'active_window_metadata' "latency proof must include the cheap active-window metadata endpoint"
    require "$LATENCY_BASELINE_PROOF" '%{http_code} %{time_total}' "latency proof must measure status and timing in one request"
    require "$LATENCY_BASELINE_PROOF" 'scrollback_chunk_80' "latency proof must include the new C4 chunk endpoint"
    require "$LATENCY_BASELINE_PROOF" 'web_config_token' "latency proof must include tokenized browser config"
    require "$LATENCY_BASELINE_PROOF" 'Phone latency baseline proof passed' "latency proof must have an explicit success receipt"
else
    echo "Phone plan regression guard failed: missing latency baseline proof script" >&2
    echo "File: $LATENCY_BASELINE_PROOF" >&2
    exit 1
fi

if [ -f "$PHONE_HOST_KEEPALIVE" ]; then
    # WHY: the 2026-06-17 phone outage proved ttyd can remain alive while the
    # control API is gone. Host keepalive must probe the actual phone-facing
    # control payloads and tmux session, then use the idempotent Mantis start
    # path instead of killing tmux or silently restarting user work.
    require "$PHONE_HOST_KEEPALIVE" 'CONTROL_TABS_URL' "host keepalive must prove the fast Active picker payload, not only the ttyd socket"
    require "$PHONE_HOST_KEEPALIVE" 'CONTROL_ACTIVE_URL' "host keepalive must prove active-window metadata, not only the ttyd socket"
    require "$PHONE_HOST_KEEPALIVE" 'tmux has-session -t "$TMUX_SESSION"' "host keepalive must prove main_phone still exists"
    require "$PHONE_HOST_KEEPALIVE" 'mantis}" phone start-host' "host keepalive must repair through the idempotent Mantis start-host path"
    require "$PHONE_HOST_KEEPALIVE" 'instead of killing tmux' "host keepalive WHY comment must preserve the no-tmux-kill boundary"
    require "$PHONE_HOST_KEEPALIVE" 'PHONE_HOST_KEEPALIVE_LOCK_STALE_SECONDS' "host keepalive must have a bounded stale-lock recovery threshold"
    require "$PHONE_HOST_KEEPALIVE" 'removed stale keepalive lock' "host keepalive must log stale lock recovery instead of skipping forever"
    require "$PHONE_HOST_KEEPALIVE" 'pgrep -u "$(id -u)" -f' "host keepalive must prove no live owner before removing a stale lock"
    require "$PHONE_HOST_KEEPALIVE" 'process_is_keepalive_owner' "host keepalive owner detection must inspect argv, not just match env text"
    require "$PHONE_HOST_KEEPALIVE" 'startup' "host keepalive must support reboot/startup cron mode"
    require "$PHONE_HOST_KEEPALIVE" '--startup' "host keepalive must support explicit startup cron mode"
else
    echo "Phone plan regression guard failed: missing host keepalive script" >&2
    echo "File: $PHONE_HOST_KEEPALIVE" >&2
    exit 1
fi

if [ -f "$APK_RELEASE_SCRIPT" ]; then
    # WHY: Mantis Remote APK updates live in the separate WEzTerm Android repo,
    # not the private Mantis bundle repo. The release lane must wait for clean,
    # pushed source before tagging and uploading the APK asset, or GitHub's
    # latest/download URL can lag behind the phone build installed locally.
    require "$APK_RELEASE_SCRIPT" 'waiting for WEzTerm source autopush before APK release' "APK release cron must wait for clean source before publishing"
    require "$APK_RELEASE_SCRIPT" 'origin/main to match local HEAD' "APK release cron must prove GitHub has the source commit before tagging"
    require "$APK_RELEASE_SCRIPT" 'gh release create "$tag" "$apk#WEzterm.apk"' "APK release cron must create the GitHub release asset"
    require "$APK_RELEASE_SCRIPT" 'gh release upload "$tag" "$apk#WEzterm.apk"' "APK release cron must refresh an existing GitHub release asset safely"
    require "$APK_RELEASE_SCRIPT" 'Stop maps to one desktop Escape' "APK release notes must preserve direct Stop behavior"
    require "$APK_RELEASE_SCRIPT" 'Enter / IME action submits through the same pinned path as Send' "APK release notes must preserve direct Enter behavior"
else
    echo "Phone plan regression guard failed: missing WEzTerm APK release script" >&2
    echo "File: $APK_RELEASE_SCRIPT" >&2
    exit 1
fi

if [ -f "$LOCAL_HISTORY_UI_PROOF" ]; then
    # WHY: C5 is only complete if the installed APK exposes the native local
