require "$ACTIVE_DOT_GRID_PROOF" 'blank_terminal_body' "active-switch proof must reject mostly black terminal-body false positives"
require "$ACTIVE_DOT_GRID_PROOF" 'v2.81 briefly passed this proof' "active-switch proof WHY comment must preserve the black-body false positive"

# WHY: Bash `-n` cannot parse embedded heredoc Python. The toolbar geometry
# proof is the guard that catches hidden composer rows and giant keyboard blanks;
# if its Python has bad indentation, the proof harness fails before it can protect
# the user-facing phone UI. Compile that heredoc here so harness regressions are
# caught before APK build or install.
python3 - "$ROOT/scripts/prove-phone-menu-ui.sh" <<'PY'
import pathlib
import sys

path = pathlib.Path(sys.argv[1])
lines = path.read_text(encoding="utf-8").splitlines()
marker = '    python3 - "$DUMP_LOCAL" "$ime_state" <<\'PY\''
try:
    start = lines.index(marker) + 1
except ValueError as exc:
    raise SystemExit(f"Phone plan regression guard failed: missing toolbar geometry Python heredoc in {path}") from exc
body = []
for line in lines[start:]:
    if line == "PY":
        break
    body.append(line)
else:
    raise SystemExit(f"Phone plan regression guard failed: unterminated toolbar geometry Python heredoc in {path}")
compile("\n".join(body) + "\n", f"{path}:assert_terminal_toolbar_geometry", "exec")
PY

echo "Phone plan regression guard passed"
